INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'teenage', 'adj.', '/ˈtiːneɪdʒ/', '十几岁的（指13至19岁）；青少年的', 'Teenage life is full of new challenges.', '青少年生活充满新挑战。', 'Teenage Life', 1, 0, 'senior', 'wordlist', 'required1', 'U1', 'teenage life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'teenager', 'n.', '/ˈtiːneɪdʒə(r)/', '（13至19岁之间的）青少年', 'Most teenagers enjoy joining school clubs.', '大多数青少年喜欢参加学校社团。', 'Teenage Life', 2, 0, 'senior', 'wordlist', 'required1', 'U1', 'a typical teenager', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'ballet', 'n.', '/ˈbæleɪ/', '芭蕾舞', 'She has a ballet class every Friday.', '她每周五有一节芭蕾课。', 'Teenage Life', 3, 0, 'senior', 'wordlist', 'required1', 'U1', 'join the ballet club', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'volunteer', 'n.', '/ˌvɒlənˈtɪə(r)/', '志愿者', 'I work as a volunteer at the weekend.', '我周末做志愿者。', 'Teenage Life', 4, 0, 'senior', 'wordlist', 'required1', 'U1', 'work as a volunteer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'debate', 'n./v.', '/dɪˈbeɪt/', '辩论；争论', 'We had a debate about computer games.', '我们就电脑游戏进行了一场辩论。', 'Teenage Life', 5, 0, 'senior', 'wordlist', 'required1', 'U1', 'have a debate', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'prefer', 'vt.', '/prɪˈfɜː(r)/', '较喜欢', 'I prefer reading to watching TV.', '比起看电视，我更喜欢读书。', 'Teenage Life', 6, 0, 'senior', 'wordlist', 'required1', 'U1', 'prefer tea to coffee', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'content', 'n.', '/ˈkɒntent/', '内容；目录；主题', 'The content of this book is very interesting.', '这本书的内容很有趣。', 'Teenage Life', 7, 0, 'senior', 'wordlist', 'required1', 'U1', 'the content of the text', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'movement', 'n.', '/ˈmuːvmənt/', '动作；运动；活动', 'The dancers practise new movements every day.', '舞者们每天练习新动作。', 'Teenage Life', 8, 0, 'senior', 'wordlist', 'required1', 'U1', 'learn new movements', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'greenhouse', 'n.', '/ˈɡriːnhaʊs/', '温室；暖房', 'We grow vegetables in the greenhouse.', '我们在温室里种蔬菜。', 'Teenage Life', 9, 0, 'senior', 'wordlist', 'required1', 'U1', 'work in a greenhouse', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'suitable', 'adj.', '/ˈsuːtəbl/', '合适的；适用的', 'This club is suitable for me.', '这个社团适合我。', 'Teenage Life', 10, 0, 'senior', 'wordlist', 'required1', 'U1', 'a suitable club for you', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'actually', 'adv.', '/ˈæktʃuəli/', '事实上；的确', 'Actually, I agree with you.', '事实上，我同意你。', 'Teenage Life', 11, 0, 'senior', 'wordlist', 'required1', 'U1', 'actually, I agree', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'challenge', 'n./vt.', '/ˈtʃælɪndʒ/', '挑战；艰巨任务', 'Senior high school is a big challenge.', '高中是一个巨大的挑战。', 'Teenage Life', 12, 0, 'senior', 'wordlist', 'required1', 'U1', 'face a big challenge', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'title', 'n.', '/ˈtaɪtl/', '名称；标题；头衔', 'What is the title of the text?', '这篇课文的标题是什么？', 'Teenage Life', 13, 0, 'senior', 'wordlist', 'required1', 'U1', 'the title of the book', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'topic', 'n.', '/ˈtɒpɪk/', '话题；标题', 'We talked about an interesting topic in class.', '我们在课上谈论了一个有趣的话题。', 'Teenage Life', 14, 0, 'senior', 'wordlist', 'required1', 'U1', 'discuss a topic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'freshman', 'n.', '/ˈfreʃmən/', '（大学或高中）一年级新生', 'He is a freshman at senior high school.', '他是高中一年级新生。', 'Teenage Life', 15, 0, 'senior', 'wordlist', 'required1', 'U1', 'a freshman at senior high', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'confusing', 'adj.', '/kənˈfjuːzɪŋ/', '难以理解的；不清楚的', 'The first week was a little confusing.', '第一周有点令人困惑。', 'Teenage Life', 16, 0, 'senior', 'wordlist', 'required1', 'U1', 'a confusing question', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'confuse', 'vt.', '/kənˈfjuːz/', '使糊涂；使迷惑', 'Don''t confuse these two words.', '不要把这两个词弄混。', 'Teenage Life', 17, 0, 'senior', 'wordlist', 'required1', 'U1', 'confuse the two words', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'confused', 'adj.', '/kənˈfjuːzd/', '糊涂的；迷惑的', 'I felt confused on my first day.', '第一天我感到困惑。', 'Teenage Life', 18, 0, 'senior', 'wordlist', 'required1', 'U1', 'feel confused', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fluent', 'adj.', '/ˈfluːənt/', '（尤指外语）流利的；熟练的', 'I hope to be fluent in English.', '我希望英语说得流利。', 'Teenage Life', 19, 0, 'senior', 'wordlist', 'required1', 'U1', 'be fluent in English', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'graduate', 'vi.', '/ˈɡrædʒueɪt/', '毕业；获得学位', 'I will study hard until I graduate.', '我会努力学习直到毕业。', 'Teenage Life', 20, 0, 'senior', 'wordlist', 'required1', 'U1', 'graduate from high school', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'recommend', 'vt.', '/ˌrekəˈmend/', '建议；推荐；介绍', 'My teacher recommended a good book to me.', '老师给我推荐了一本好书。', 'Teenage Life', 21, 0, 'senior', 'wordlist', 'required1', 'U1', 'recommend a good book', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'advanced', 'adj.', '/ədˈvɑːnst/', '高级的；高等的；先进的', 'She signed up for an advanced English course.', '她报名了一门高级英语课程。', 'Teenage Life', 22, 0, 'senior', 'wordlist', 'required1', 'U1', 'an advanced course', '英音 /ɑː/，美音 /æ/;美音 /ədˈvænst/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'advance', 'n./v.', '/ədˈvɑːns/', '前进；发展', 'Science makes new advances every year.', '科学每年都有新的发展。', 'Teenage Life', 23, 0, 'senior', 'wordlist', 'required1', 'U1', 'advances in science', '英音 /ɑː/，美音 /æ/;美音 /ədˈvæns/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'literature', 'n.', '/ˈlɪtrətʃə(r)/', '文学；文学作品', 'I really enjoy English literature.', '我很喜欢英语文学。', 'Teenage Life', 24, 0, 'senior', 'wordlist', 'required1', 'U1', 'English literature', '英音 /-tʃə/，美音 /-tʃʊr/ 卷舌且常多一个音节;美音 /ˈlɪtərətʃʊr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extra-curricular', 'adj.', '/ˌekstrəkəˈrɪkjələ(r)/', '课外的；课程以外的', 'He takes part in many extra-curricular activities.', '他参加许多课外活动。', 'Teenage Life', 25, 0, 'senior', 'wordlist', 'required1', 'U1', 'extra-curricular activities', '美音词尾 /-lər/ 卷舌 r;美音 /ˌekstrəkəˈrɪkjələr/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'extra', 'adj.', '/ˈekstrə/', '额外的；附加的', 'The teacher gave us some extra homework.', '老师给我们布置了一些额外的作业。', 'Teenage Life', 26, 0, 'senior', 'wordlist', 'required1', 'U1', 'extra homework', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'obviously', 'adv.', '/ˈɒbviəsli/', '显然；明显地', 'He was obviously very happy about the news.', '他显然对这个消息很高兴。', 'Teenage Life', 27, 0, 'senior', 'wordlist', 'required1', 'U1', 'obviously important', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'quit', 'v.', '/kwɪt/', '停止；戒掉；离开', 'Don''t quit when things get difficult.', '困难的时候不要放弃。', 'Teenage Life', 28, 0, 'senior', 'wordlist', 'required1', 'U1', 'never quit trying', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'responsible', 'adj.', '/rɪˈspɒnsəbl/', '负责的；有责任的', 'You should be responsible for your own studies.', '你应该对自己的学业负责。', 'Teenage Life', 29, 0, 'senior', 'wordlist', 'required1', 'U1', 'be responsible for it', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'responsibility', 'n.', '/rɪˌspɒnsəˈbɪləti/', '责任；义务', 'Looking after a pet is a big responsibility.', '照顾宠物是一项重大的责任。', 'Teenage Life', 30, 0, 'senior', 'wordlist', 'required1', 'U1', 'take responsibility', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'solution', 'n.', '/səˈluːʃn/', '解决办法；答案', 'We finally found a good solution to the problem.', '我们最终找到了解决问题的好办法。', 'Teenage Life', 31, 0, 'senior', 'wordlist', 'required1', 'U1', 'find a solution', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'schedule', 'n.', '/ˈʃedjuːl/', '工作计划；日程安排', 'I made a study schedule for this week.', '我为这周制定了一份学习计划。', 'Teenage Life', 32, 0, 'senior', 'wordlist', 'required1', 'U1', 'a busy schedule', '英音 /ʃ-/（sh-），美音 /sk-/（sk-）;美音 /ˈskedʒuːl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'editor', 'n.', '/ˈedɪtə(r)/', '主编；编辑；编者', 'She wants to be a magazine editor one day.', '她希望有一天成为杂志编辑。', 'Teenage Life', 33, 0, 'senior', 'wordlist', 'required1', 'U1', 'a magazine editor', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'adventure', 'n.', '/ədˈventʃə(r)/', '冒险；奇遇', 'The summer trip was a great adventure.', '那次暑期旅行是一场了不起的冒险。', 'Teenage Life', 34, 0, 'senior', 'wordlist', 'required1', 'U1', 'a great adventure', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'youth', 'n.', '/juːθ/', '青年时期；青春', 'Music was very important to him in his youth.', '音乐在他青年时期对他很重要。', 'Teenage Life', 35, 0, 'senior', 'wordlist', 'required1', 'U1', 'in his youth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'survival', 'n.', '/səˈvaɪvl/', '生存；幸存', 'They learned survival skills at the camp.', '他们在营地学习生存技能。', 'Teenage Life', 36, 0, 'senior', 'wordlist', 'required1', 'U1', 'survival skills', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'expert', 'n.', '/ˈekspɜːt/', '专家；行家', 'My uncle is a computer expert.', '我叔叔是电脑专家。', 'Teenage Life', 37, 0, 'senior', 'wordlist', 'required1', 'U1', 'a computer expert', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'behaviour', 'n.', '/bɪˈheɪvjə(r)/', '行为；举止', 'Good behaviour is important at school.', '良好的行为在学校很重要。', 'Teenage Life', 38, 0, 'senior', 'wordlist', 'required1', 'U1', 'good behaviour', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'generation', 'n.', '/ˌdʒenəˈreɪʃn/', '一代（人）', 'The younger generation loves the Internet.', '年轻一代喜欢互联网。', 'Teenage Life', 39, 0, 'senior', 'wordlist', 'required1', 'U1', 'the younger generation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'attract', 'vt.', '/əˈtrækt/', '吸引；引起注意', 'The new club attracted many students.', '新社团吸引了许多学生。', 'Teenage Life', 40, 0, 'senior', 'wordlist', 'required1', 'U1', 'attract attention', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'focus', 'v./n.', '/ˈfəʊkəs/', '集中（注意力）；焦点', 'You should focus on your studies.', '你应该专注于学业。', 'Teenage Life', 41, 0, 'senior', 'wordlist', 'required1', 'U1', 'focus on your studies', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'addicted', 'adj.', '/əˈdɪktɪd/', '有瘾的；上瘾的；入迷的', 'Some teenagers are addicted to computer games.', '一些青少年沉迷于电脑游戏。', 'Teenage Life', 42, 0, 'senior', 'wordlist', 'required1', 'U1', 'addicted to games', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'addict', 'n.', '/ˈædɪkt/', '对…入迷的人；瘾君子', 'He used to be a computer game addict.', '他曾经是个电脑游戏迷。', 'Teenage Life', 43, 0, 'senior', 'wordlist', 'required1', 'U1', 'a game addict', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'adult', 'n.', '/ˈædʌlt/', '成年人', 'Every adult was once a child.', '每个成年人都曾是孩子。', 'Teenage Life', 44, 0, 'senior', 'wordlist', 'required1', 'U1', 'a responsible adult', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r1u1.01', '①名词短语 Noun Phrase (NP)', 'B1', 10, '必修一 U1 — 以名词为中心词的词组（如 a difficult language / the school adviser / most of my classmates）。在句中作主语、宾语或表语。判断看中心词是不是名词。', 1, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r1u1.02', '②形容词短语 Adjective Phrase (AdjP)', 'B1', 10, '必修一 U1 — 以形容词为中心词的词组（如 a little confusing / good at English / addicted to games / very nice and patient）。常作表语、定语或宾语补足语,许多需固定介词搭配。判断看中心词是不是形容词。', 2, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r1u1.03', '③副词短语 Adverb Phrase (AdvP)', 'B1', 10, '必修一 U1 — 以副词为中心词的词组（如 quite quickly / pretty soon / well enough / too fast）。作状语,修饰动词、形容词或其他副词。判断看中心词是不是副词。', 3, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"We should respect ____."', 'other people', 'very polite', 'quite often', 'afraid of failure', 'A', 'respect 后接宾语需名词短语 other people;其余是形容词短语/副词短语,不能作宾语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"My adviser recommended ____."', 'advanced literature', 'very advanced', 'quite carefully', 'read widely', 'A', 'recommended 后接宾语用名词短语 advanced literature;very advanced 是形容词短语,quite carefully 是副词短语,read widely 是动词短语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"Every Wednesday we hand out food to ____."', 'homeless people', 'very poor', 'quite hungry', 'live nearby', 'A', '介词 to 后接名词短语 homeless people;其余是形容词短语/动词短语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"On the first day I made ____."', 'some new friends', 'very friendly', 'quite quickly', 'get along', 'A', 'made 后接宾语用名词短语 some new friends;very friendly 是形容词短语,quite quickly 是副词短语,get along 是动词短语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"The school adviser helped me choose ____."', 'some suitable courses', 'very suitable', 'quite easily', 'easy to learn', 'A', 'choose 后接宾语用名词短语 some suitable courses;其余是形容词短语/副词短语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"He told us ____ in class."', 'a funny story', 'very funny', 'fun to hear', 'tell jokes', 'A', 'told us 后接直接宾语用名词短语 a funny story;其余是形容词短语/动词短语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"I finally joined ____."', 'a volunteer club', 'very active', 'quite often', 'keen on sports', 'A', 'joined 后接宾语用名词短语 a volunteer club;其余是形容词短语/副词短语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"I''m a bit worried about ____."', 'all the homework', 'very busy', 'quite hard', 'hard to finish', 'A', '介词 about 后接名词短语 all the homework;其余是形容词短语,不能作介词宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"The coach gave me ____."', 'some good advice', 'very useful', 'quite kindly', 'help a lot', 'A', 'gave me 后接直接宾语用名词短语 some good advice;其余是形容词短语/副词短语/动词短语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"I hope to be fluent in ____ one day."', 'a foreign language', 'very fluent', 'quite well', 'hard to learn', 'A', 'be fluent in 后接名词短语 a foreign language;其余是形容词短语/副词短语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"____ is a big challenge for freshmen."', 'The first week', 'Quite hard', 'Very busy', 'Hard to manage', 'A', '句首作主语用名词短语 The first week;其余是副词短语/形容词短语,不能作主语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '选出能填入空白的名词短语:"Teenagers should take ____ for their own studies."', 'responsibility', 'responsible', 'responsibly', 'very seriously', 'A', 'take 后接宾语用名词 responsibility(名词短语);responsible 是形容词,responsibly/very seriously 是副词(短语)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '下列哪一项是名词短语(noun phrase)?', 'a foreign language', 'very interesting', 'quite carefully', 'good at English', 'A', 'a foreign language 中心词是名词 language;very interesting 是形容词短语,quite carefully 是副词短语,good at English 是形容词短语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '下列哪一项是名词短语?', 'the new student', 'fast asleep', 'extremely tired', 'run quickly', 'A', 'the new student 中心词是名词 student;fast asleep / extremely tired 是形容词短语,run quickly 是动词短语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '句子 "The first week was a little confusing." 中,"The first week" 作____。', '主语', '宾语', '表语', '状语', 'A', 'The first week 是名词短语,位于句首作主语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '句子 "I joined a volunteer club." 中,"a volunteer club" 作____。', '宾语', '主语', '表语', '状语', 'A', 'a volunteer club 是名词短语,作动词 joined 的宾语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '句子 "Adam is a senior high school student." 中,"a senior high school student" 作____。', '表语', '主语', '宾语', '状语', 'A', '该名词短语在系动词 is 后作表语,说明主语身份。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '下列哪一项不是名词短语?', 'good at maths', 'a difficult course', 'the school adviser', 'my favourite subject', 'A', 'good at maths 中心词是形容词 good,是形容词短语;其余三项中心词都是名词。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '句子 "He told us a funny story." 中,"a funny story" 作____。', '直接宾语', '主语', '表语', '状语', 'A', 'told sb sth 结构里,us 是间接宾语,a funny story 是直接宾语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.01'), '句子 "Chinese is a very difficult language." 中,"a very difficult language" 整体是____。', '名词短语', '形容词短语', '副词短语', '动词短语', 'A', '整个短语中心词是名词 language,very difficult 只是其中的修饰语,故整体是名词短语。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Many teenagers are ____ computer games."', 'addicted to', 'addicted in', 'addicted with', 'addicted at', 'A', 'be addicted to sth 是固定搭配,意为“对……上瘾”,介词只能用 to。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"The teacher is always ____ his students."', 'patient with', 'patient to', 'patient for', 'patient at', 'A', 'be patient with sb 表示“对某人有耐心”,介词用 with。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"I''m really ____ English literature."', 'interested in', 'interested on', 'interested at', 'interested for', 'A', 'be interested in sth 表示“对……感兴趣”,介词用 in。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"After years of practice, she is ____ Chinese."', 'fluent in', 'fluent at', 'fluent on', 'fluent with', 'A', 'be fluent in a language 表示“某语言流利”,介词用 in。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"As the captain, you are ____ keeping the team together."', 'responsible for', 'responsible of', 'responsible with', 'responsible at', 'A', 'be responsible for sth 表示“对……负责”,介词用 for。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Don''t be ____ making mistakes — everyone does."', 'afraid of', 'afraid to', 'afraid for', 'afraid at', 'A', 'be afraid of doing sth 表示“害怕做某事”;此处接动名词 making,用 of(afraid to 后须接动词原形)。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Adam is quite ____ maths and science."', 'good at', 'good in', 'good on', 'good for', 'A', 'be good at sth 表示“擅长……”,介词用 at。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Are you ____ joining the music club?"', 'keen on', 'keen at', 'keen in', 'keen for', 'A', 'be keen on (doing) sth 表示“热衷于……”,介词用 on。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"The coach is ____ his strong team."', 'proud of', 'proud for', 'proud at', 'proud in', 'A', 'be proud of sb/sth 表示“为……自豪”,介词用 of。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Many freshmen are ____ the new courses."', 'worried about', 'worried for', 'worried on', 'worried at', 'A', 'be worried about sth 表示“为……担心”,介词用 about。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出正确的形容词短语填空:"Our monitor is always ____ help others."', 'ready to', 'ready for', 'ready of', 'ready at', 'A', 'be ready to do sth 表示“乐意/准备做某事”,后接动词原形 help,用 to。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '选出能填入空白的形容词(短语):"It is ____ to make a workable schedule."', 'important', 'importantly', 'importance', 'to import', 'A', '"It is + 形容词 + to do" 结构,空处作表语用形容词 important;importantly 是副词,importance 是名词,to import 是动词不定式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '下列哪一项是形容词短语(adjective phrase)?', 'good at sports', 'the football team', 'very well', 'play basketball', 'A', 'good at sports 中心词是形容词 good;the football team 是名词短语,very well 是副词短语,play basketball 是动词短语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '下列哪一项是形容词短语?', 'very nice and patient', 'my new teachers', 'quite quickly', 'make friends', 'A', '中心词是形容词 nice/patient;my new teachers 是名词短语,quite quickly 是副词短语,make friends 是动词短语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '句子 "The first week was a little confusing." 中,"a little confusing" 作____。', '表语', '主语', '宾语', '定语', 'A', '形容词短语 a little confusing 在系动词 was 后作表语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '句子 "I found the lesson very interesting." 中,"very interesting" 作____。', '宾语补足语', '表语', '主语', '状语', 'A', 'found + 宾语 the lesson + 形容词短语 very interesting 作宾语补足语,说明宾语状态。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '下列哪一项不是形容词短语?', 'a busy schedule', 'afraid of the dark', 'ready to help', 'full of energy', 'A', 'a busy schedule 中心词是名词 schedule,是名词短语;其余三项中心词都是形容词。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '句子 "The building is so big that I''m lost." 中,"so big" 作____。', '表语', '主语', '宾语', '状语', 'A', '形容词短语 so big 在系动词 is 后作表语。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '下列哪一项是形容词短语?', 'difficult to choose', 'a hard choice', 'quite quickly', 'choose a course', 'A', 'difficult to choose 中心词是形容词 difficult;a hard choice 是名词短语,quite quickly 是副词短语,choose a course 是动词短语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.02'), '句子 "The new coach made the team stronger." 中,"stronger" 作____。', '宾语补足语', '表语', '主语', '状语', 'A', 'made + 宾语 the team + 形容词 stronger 作宾语补足语。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"You''ll finish the homework ____."', 'pretty soon', 'very busy', 'a long time', 'hard work', 'A', '修饰动词 finish 作状语用副词短语 pretty soon;very busy 是形容词短语,a long time / hard work 是名词短语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"He answered the question ____."', 'very politely', 'very polite', 'a polite way', 'be polite', 'A', '修饰动词 answered 用副词短语 very politely;very polite 是形容词短语,a polite way 是名词短语,be polite 是动词短语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"Please read the new words ____."', 'aloud and clearly', 'loud and clear', 'a clear voice', 'very clear', 'A', '修饰动词 read 用副词短语 aloud and clearly;loud and clear / very clear 是形容词短语,a clear voice 是名词短语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"The teacher spoke ____, so I couldn''t follow."', 'too fast', 'too quick', 'a fast speaker', 'very fast speech', 'A', '修饰动词 spoke 用副词短语 too fast(fast 此处为副词);too quick 是形容词短语,后两项是名词短语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"Rita plays the violin ____."', 'quite well', 'quite good', 'a good player', 'very nice', 'A', '修饰动词 plays 用副词短语 quite well;quite good / very nice 是形容词短语,a good player 是名词短语。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"My French class went ____."', 'surprisingly well', 'surprisingly good', 'a good class', 'very nice', 'A', '修饰动词 went 用副词短语 surprisingly well;surprisingly good / very nice 是形容词短语,a good class 是名词短语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"He runs ____ now than before."', 'much faster', 'very fast speed', 'a fast runner', 'quite quick', 'A', '修饰动词 runs 且用于比较用副词短语 much faster;quite quick 是形容词短语,其余是名词短语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"If you practise every day, you''ll improve ____."', 'quite quickly', 'quite quick', 'a quick way', 'very quick', 'A', '修饰动词 improve 用副词短语 quite quickly;quite quick / very quick 是形容词短语,a quick way 是名词短语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"She speaks English ____."', 'very fast', 'very quick', 'a fast mind', 'quite clever', 'A', '修饰动词 speaks 用副词短语 very fast(fast 作副词);very quick / quite clever 是形容词短语,a fast mind 是名词短语。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词(性)短语:"I''ll improve ____ so I can make the team."', 'on my own', 'my own effort', 'very independent', 'work alone', 'A', 'on my own 等于副词 independently,修饰 improve 作方式状语;my own effort 是名词短语,very independent 是形容词短语,work alone 是动词短语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"She finished the test ____ than me."', 'more quickly', 'more quick', 'a quick test', 'very fast', 'A', '比较级状语修饰 finished 用副词短语 more quickly;more quick 形式错误,a quick test 是名词短语,very fast 无比较含义不搭 than。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '选出能填入空白的副词短语:"The team members work ____."', 'very well together', 'very good', 'a good team', 'get along', 'A', '修饰动词 work 用副词短语 very well together;very good 是形容词短语,a good team 是名词短语,get along 是动词短语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '下列哪一项是副词短语(adverb phrase)?', 'quite quickly', 'very quick', 'a quick reply', 'quick to answer', 'A', 'quite quickly 中心词是副词 quickly;very quick / quick to answer 是形容词短语,a quick reply 是名词短语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '下列哪一项是副词短语?', 'very carefully', 'a careful plan', 'careful enough', 'take care', 'A', 'very carefully 中心词是副词 carefully;a careful plan 是名词短语,careful enough 是形容词短语,take care 是动词短语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '句子 "Linda thinks and speaks quite quickly." 中,"quite quickly" 作____。', '状语', '表语', '宾语', '定语', 'A', '副词短语 quite quickly 修饰动词 thinks and speaks,作状语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '句子 "I didn''t play well enough." 中,"well enough" 作____。', '状语', '表语', '宾语', '主语', 'A', '副词短语 well enough 修饰动词 play,作状语。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '下列哪一项不是副词短语?', 'a good result', 'rather slowly', 'quite often', 'very carefully', 'A', 'a good result 中心词是名词 result,是名词短语;其余三项中心词都是副词。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '句子 "We worked together very well." 中,"very well" 修饰的是____。', '动词 worked', '名词 we', '形容词 together', '整个句子', 'A', '副词短语 very well 作状语,修饰动词 worked,说明做事的方式。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '下列哪一项是副词短语?', 'extremely hard', 'a hard worker', 'work hard', 'hard to follow', 'A', 'extremely hard 中 hard 是副词(努力地),受 extremely 修饰,是副词短语;a hard worker 是名词短语,work hard 是动词短语,hard to follow 是形容词短语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required1' AND unit='U1' AND code='r1u1.03'), '下列哪一项是副词短语?', 'right now', 'the right answer', 'be right', 'right to do', 'A', 'right now 中心词是副词 now;the right answer 是名词短语,be right 是动词短语,right to do 是形容词短语。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Freshman Challenge', 'Hi! My name is Adam and I''m a freshman at senior high school. Going from junior high school to senior high school is a really big challenge, and my first week was a little confusing. First, I had to think carefully about which courses I wanted to take. The school adviser helped me choose the suitable ones: maths, English, chemistry, world history, and Chinese. I know that Chinese is a very difficult language, but I hope to be fluent when I graduate. My adviser also recommended that I should sign up for advanced literature, because I like English and I''m good at it. I had to choose extra-curricular activities, too. I tried to join the school football team, but the coach told me that I didn''t play well enough. Obviously, I was unhappy, but I won''t quit. I''ll find a way to improve on my own so that I can make the team next year. Instead, I joined a volunteer club. Every Wednesday, we hand out food to homeless people in the community. I know I''ll have to study harder and get used to being responsible for a lot more. Still, I''m happy to be here, and I''ll be well prepared for whatever comes in the future.', '记叙·新生挑战', 207, '[{"q":"Why was Adam''s first week of senior high school \"a little confusing\"?","answer":"A","options":["He had to make many new choices, such as courses and activities.","He could not find his classroom.","He did not know any of the teachers.","He was new to the city."],"explanation":"首段说他要仔细选课、选课外活动,新选择多,所以感到 confusing。"},{"q":"Why did the adviser recommend advanced literature to Adam?","answer":"A","options":["Because Adam likes English and is good at it.","Because it is an easy course.","Because Chinese is too difficult.","Because the football team needed him."],"explanation":"原文:because I like English and I''m good at it。"},{"q":"What does \"make the team\" in the passage mean?","answer":"A","options":["To be chosen as a member of the team.","To set up a new team.","To beat the other team.","To train the team."],"explanation":"make the team 指被选进球队;他说明年要 improve 才能进队。"},{"q":"What can we learn about Adam from the passage?","answer":"A","options":["He stays positive and does not give up easily.","He regrets coming to senior high school.","He dislikes all his courses.","He has given up sports for ever."],"explanation":"他没进球队但说 I won''t quit、I''ll find a way to improve,且 happy to be here,可见积极不放弃。"}]'::jsonb, '[{"word":"freshman","cn":"(高中)一年级新生"},{"word":"challenge","cn":"挑战"},{"word":"fluent","cn":"流利的"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Letter of Advice', 'Dear Worried Friend, You wrote that you are very worried about your friend, Chen Lei. I understand quite well that you feel anxious. You think that your friend plays computer games too often and spends too much time online. I recommend that you talk to your friend about his behaviour. It is not unusual for teenagers of your generation to be attracted to computer games and the online world. But spending too much time online is unhealthy, and it makes it very difficult to focus on other things in life. Some students even become addicted to the Internet and cannot concentrate on school and family life. I think you should encourage your friend to try new hobbies. Why not discuss the problem together? I am sure he will listen to you, since you are his good friend. All the best, Susan Luo', '应用·建议信', 142, '[{"q":"According to the letter, what is Chen Lei''s problem?","answer":"A","options":["He spends too much time playing computer games online.","He never does his homework.","He has no friends at school.","He is often late for class."],"explanation":"信中说 your friend plays computer games too often and spends too much time online。"},{"q":"What is Susan Luo''s main piece of advice?","answer":"A","options":["Talk to the friend and encourage him to try new hobbies.","Report the friend to the teacher.","Stop being his friend.","Take away his computer."],"explanation":"她建议 talk to your friend about his behaviour 并 encourage him to try new hobbies。"},{"q":"According to the letter, why is spending too much time online a problem?","answer":"A","options":["It is unhealthy and makes it hard to focus on other things.","It costs too much money.","It is against school rules.","It makes people fluent in English."],"explanation":"原文:unhealthy, and it makes it very difficult to focus on other things in life。"},{"q":"Why does Susan Luo think the friend will listen?","answer":"A","options":["Because they are good friends.","Because she is a teacher.","Because his parents asked him to.","Because he is afraid of her."],"explanation":"原文:I am sure he will listen to you, since you are his good friend。"}]'::jsonb, '[{"word":"behaviour","cn":"行为；举止"},{"word":"addicted","cn":"上瘾的"},{"word":"focus","cn":"集中(注意力)"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Choosing the Right Club', 'At senior high school, there are many clubs for students to join. Each club has its own activities. In the Ballet Club, students learn new movements and dance together. In the Nature Club, they grow plants and work in a greenhouse. Members of the Debate Club enjoy discussing different topics, and they think and speak quite quickly. The Volunteer Club is also popular: its members help old people and clean up parks at the weekend. So how can you choose a suitable club? First, think about what you are interested in. If you love animals and plants, the Nature Club may be a good choice. Second, think about what you are good at. A student who speaks well may do well in the Debate Club. Finally, remember that a club should be fun, not just useful. The right club can help you make new friends and learn something new outside class.', '说明·选社团', 151, '[{"q":"What do members of the Nature Club do?","answer":"A","options":["Grow plants and work in a greenhouse.","Learn new dance movements.","Help old people.","Debate different topics."],"explanation":"原文:In the Nature Club, they grow plants and work in a greenhouse。"},{"q":"According to the passage, who may do well in the Debate Club?","answer":"A","options":["A student who speaks well.","A student who loves plants.","A student who can dance.","A student who likes cleaning parks."],"explanation":"原文:A student who speaks well may do well in the Debate Club。"},{"q":"What is the FIRST thing you should think about when choosing a club?","answer":"A","options":["What you are interested in.","How much it costs.","Which club your friends joined.","How far the club is."],"explanation":"原文:First, think about what you are interested in。"},{"q":"What is the main idea of the passage?","answer":"A","options":["How to choose a suitable school club.","Why ballet is difficult to learn.","How to grow plants in a greenhouse.","Why debate is the best club."],"explanation":"全文介绍各社团并给出选社团的方法,主旨是如何选合适的社团。"}]'::jsonb, '[{"word":"suitable","cn":"合适的"},{"word":"greenhouse","cn":"温室"},{"word":"debate","cn":"辩论"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Managing Your Time at Senior High', 'Senior high school students often feel that there is never enough time. They have more homework, more subjects, and more extra-curricular activities than before. Being responsible for so much can be a real challenge. So how can teenagers manage their time well? The answer is to make a schedule. A schedule is a plan that shows what you will do and when. First, write down the most important tasks, such as homework and review. Then decide how much time each task needs. It is also wise to leave some free time for sports or hobbies, because all work and no play is not healthy. When you follow your schedule, you will feel less anxious and get more done. Good time management will not happen in one day, but if you keep trying, it will soon become a useful habit.', '说明·时间管理', 139, '[{"q":"Why do senior high students often feel there is not enough time?","answer":"A","options":["They have more homework, subjects and activities.","They sleep too much.","They have no hobbies.","Their classes are too short."],"explanation":"原文:more homework, more subjects, and more extra-curricular activities than before。"},{"q":"According to the passage, what is a schedule?","answer":"A","options":["A plan that shows what you will do and when.","A list of your friends.","A kind of homework.","A school club."],"explanation":"原文:A schedule is a plan that shows what you will do and when。"},{"q":"Why should you leave some free time in your schedule?","answer":"A","options":["Because all work and no play is not healthy.","Because homework is not important.","Because teachers ask you to.","Because you have nothing to do."],"explanation":"原文:leave some free time ... because all work and no play is not healthy。"},{"q":"What does the writer think about good time management?","answer":"A","options":["It takes time but can become a useful habit.","It is impossible for teenagers.","It happens in only one day.","It is a waste of time."],"explanation":"原文:will not happen in one day, but if you keep trying, it will soon become a useful habit。"}]'::jsonb, '[{"word":"schedule","cn":"日程安排"},{"word":"responsible","cn":"负责的"},{"word":"anxious","cn":"焦虑的"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'First Impressions', 'So this is it — senior high school at last! I''m not very outgoing, so I felt a little anxious on my first morning. I wanted to make a good first impression, but I kept thinking: Will I make any friends? What if no one talks to me? My first maths class was difficult, but the teacher was kind and friendly. He even told us a funny story, and everyone laughed so much! I found most of my classmates and teachers friendly and helpful. In the afternoon, we had a chemistry class in the science lab. The lab was new, but the guy next to me talked the whole time, and I couldn''t concentrate on the experiment. By the evening, I felt much better. This morning I was worried that no one would talk to me, but I was wrong. I didn''t feel awkward or frightened at all. I miss my old friends, but I believe I''ll make new ones here. I feel much more confident than I did this morning. I think tomorrow will be a great day!', '记叙·开学第一天', 179, '[{"q":"Why did the writer feel anxious on the first morning?","answer":"A","options":["She is not very outgoing and worried about making friends.","She forgot her textbooks.","She was late for class.","She did not like the school."],"explanation":"原文:I''m not very outgoing ... Will I make any friends? What if no one talks to me?"},{"q":"How was the writer''s first maths class?","answer":"A","options":["Difficult, but the teacher was kind and friendly.","Easy and boring.","Cancelled because of the lab.","Too noisy to hear anything."],"explanation":"原文:My first maths class was difficult, but the teacher was kind and friendly。"},{"q":"Why couldn''t the writer concentrate in the chemistry class?","answer":"A","options":["The guy next to her talked the whole time.","The lab was too old.","She felt sick.","The teacher spoke too fast."],"explanation":"原文:the guy next to me talked the whole time, and I couldn''t concentrate on the experiment。"},{"q":"How did the writer feel by the evening?","answer":"A","options":["More confident than in the morning.","More anxious than before.","Angry with her classmates.","Sorry that she came to the school."],"explanation":"原文:I feel much more confident than I did this morning。"}]'::jsonb, '[{"word":"impression","cn":"印象"},{"word":"concentrate","cn":"集中精力"},{"word":"confident","cn":"自信的"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Growing Up and Taking Responsibility', 'Being a teenager is not always easy. As we grow up, we have to be responsible for more and more things. At home, we should help our parents and take care of ourselves. At school, we are responsible for our own studies and behaviour. Some teenagers think that being responsible means losing their freedom, but this is not true. In fact, responsibility and freedom go together. When you show that you can be responsible, adults trust you more and give you more freedom. For example, if you always finish your homework on time, your parents will not worry about your studies. If you keep your promises, your friends will believe in you. Of course, no one becomes responsible in a single day. We all make mistakes, but mistakes are a normal part of growing up. What matters is that we learn from them and keep trying to do better.', '议论·成长与责任', 149, '[{"q":"What does the writer say teenagers are responsible for at school?","answer":"A","options":["Their own studies and behaviour.","Cleaning the whole school.","Teaching younger students.","Cooking for their classmates."],"explanation":"原文:At school, we are responsible for our own studies and behaviour。"},{"q":"What is the writer''s opinion about responsibility and freedom?","answer":"A","options":["They go together.","They have nothing to do with each other.","Freedom is more important than responsibility.","Responsibility means losing all freedom."],"explanation":"原文:responsibility and freedom go together。"},{"q":"According to the passage, what happens when you show you are responsible?","answer":"A","options":["Adults trust you more and give you more freedom.","You get less free time.","You have to do more homework.","Your friends stop believing you."],"explanation":"原文:adults trust you more and give you more freedom。"},{"q":"What does the writer think about making mistakes?","answer":"A","options":["They are a normal part of growing up.","They should never happen.","They mean you are not responsible.","They are always the parents'' fault."],"explanation":"原文:mistakes are a normal part of growing up。"}]'::jsonb, '[{"word":"responsibility","cn":"责任"},{"word":"generation","cn":"一代人"},{"word":"mistake","cn":"错误"}]'::jsonb, 3, 'required1', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'Joining a School Club', 'There are many clubs at our school, and each one is (1)____ for different students. If you love dancing, the Ballet Club is a good (2)____. If you are (3)____ in plants and animals, you can join the Nature Club. Students who like to (4)____ different topics often choose the Debate Club. Last week, I decided to (5)____ up for the Volunteer Club. Every Saturday, we (6)____ up the park and help old people. At first I was a little (7)____ because I knew no one. But the other members were very (8)____, and soon I made some new (9)____. Joining a club is a great way to (10)____ your free time well.', 113, 3, '[{"q":"1","answer":"A","options":["suitable","difficult","boring","angry"],"explanation":"be suitable for 对……合适。"},{"q":"2","answer":"C","options":["problem","mistake","choice","question"],"explanation":"a good choice 一个好选择。"},{"q":"3","answer":"D","options":["good","afraid","ready","interested"],"explanation":"be interested in 对……感兴趣。"},{"q":"4","answer":"B","options":["dance","discuss","grow","clean"],"explanation":"辩论社的人喜欢 discuss(讨论)不同话题。"},{"q":"5","answer":"A","options":["sign","give","look","get"],"explanation":"sign up for 报名参加。"},{"q":"6","answer":"C","options":["look","give","clean","put"],"explanation":"clean up the park 打扫公园。"},{"q":"7","answer":"D","options":["happy","proud","glad","anxious"],"explanation":"because I knew no one,所以感到 anxious(焦虑)。"},{"q":"8","answer":"B","options":["angry","friendly","lazy","boring"],"explanation":"其他成员很 friendly(友好),所以很快交到朋友。"},{"q":"9","answer":"A","options":["friends","problems","mistakes","clubs"],"explanation":"made some new friends 交到新朋友。"},{"q":"10","answer":"C","options":["waste","lose","use","miss"],"explanation":"use your free time well 善用空闲时间。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'My First Day at Senior High', 'So this is senior high school at (1)____! On my first morning, I felt a little (2)____ because I am not very outgoing. I really wanted to make a good first (3)____. My first maths class was (4)____, but the teacher was kind and told us a funny (5)____. Everyone (6)____ so much! I found most of my classmates (7)____ and helpful. In the afternoon, the boy next to me talked the whole time, so I could not (8)____ on the experiment. By the evening, I felt much more (9)____ than in the morning. I think tomorrow will be a great (10)____.', 102, 3, '[{"q":"1","answer":"D","options":["home","night","school","last"],"explanation":"at last 终于。"},{"q":"2","answer":"B","options":["lucky","anxious","proud","happy"],"explanation":"because not very outgoing,所以有点 anxious(紧张)。"},{"q":"3","answer":"A","options":["impression","idea","plan","lesson"],"explanation":"make a good first impression 留下好的第一印象。"},{"q":"4","answer":"C","options":["easy","short","difficult","free"],"explanation":"but the teacher was kind 表转折,说明课 difficult(难)。"},{"q":"5","answer":"D","options":["song","game","word","story"],"explanation":"told us a funny story 讲了个有趣的故事。"},{"q":"6","answer":"B","options":["cried","laughed","slept","left"],"explanation":"funny story 让 everyone laughed(大笑)。"},{"q":"7","answer":"A","options":["friendly","angry","tired","busy"],"explanation":"classmates friendly and helpful 同学友好乐于助人。"},{"q":"8","answer":"C","options":["depend","agree","concentrate","win"],"explanation":"concentrate on 专注于;被打扰所以无法专注。"},{"q":"9","answer":"D","options":["tired","angry","anxious","confident"],"explanation":"傍晚比早晨更 confident(自信)。"},{"q":"10","answer":"B","options":["week","day","class","year"],"explanation":"tomorrow will be a great day 明天会是美好的一天。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'Making a Study Schedule', 'Senior high school keeps students very (1)____. They have more homework and more (2)____ than before. To manage your time well, you should make a (3)____. First, write down the most (4)____ tasks, such as homework and review. Then (5)____ how much time each task needs. It is also (6)____ to leave some free time for sports, because all work and no play is not (7)____. When you (8)____ your schedule, you will feel less (9)____ and get more done. Good time management will become a useful habit if you keep (10)____.', 92, 3, '[{"q":"1","answer":"A","options":["busy","free","lazy","quiet"],"explanation":"keep sb busy 使某人忙碌;作业、科目多,所以学生很忙。"},{"q":"2","answer":"C","options":["friends","clubs","subjects","games"],"explanation":"more homework and more subjects 更多作业和科目。"},{"q":"3","answer":"D","options":["mistake","promise","choice","schedule"],"explanation":"make a schedule 制定日程表。"},{"q":"4","answer":"B","options":["boring","important","funny","easy"],"explanation":"the most important tasks 最重要的任务。"},{"q":"5","answer":"A","options":["decide","forget","refuse","win"],"explanation":"decide how much time 决定需要多少时间。"},{"q":"6","answer":"C","options":["wrong","late","wise","hard"],"explanation":"it is wise to leave free time 留出空闲时间是明智的。"},{"q":"7","answer":"D","options":["happy","ready","clear","healthy"],"explanation":"all work and no play is not healthy 只学不玩不健康。"},{"q":"8","answer":"B","options":["break","follow","lose","miss"],"explanation":"follow your schedule 遵守日程表。"},{"q":"9","answer":"A","options":["anxious","proud","free","happy"],"explanation":"feel less anxious 不那么焦虑。"},{"q":"10","answer":"C","options":["sleeping","playing","trying","leaving"],"explanation":"keep trying 坚持努力。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'A Letter About a Friend', 'Dear Worried Friend, You wrote that you are (1)____ about your friend, Chen Lei. You think he plays computer games too (2)____ and spends too much time (3)____. I (4)____ that you talk to him about his (5)____. It is not unusual for teenagers to be (6)____ to computer games. But spending too much time online is (7)____ and makes it hard to (8)____ on other things. I think you should (9)____ him to try new hobbies. I am sure he will (10)____ to you, because you are his good friend. All the best, Susan', 95, 3, '[{"q":"1","answer":"D","options":["happy","proud","sure","worried"],"explanation":"be worried about 为……担心。"},{"q":"2","answer":"B","options":["soon","often","well","early"],"explanation":"plays games too often 玩游戏太频繁。"},{"q":"3","answer":"A","options":["online","alone","aloud","away"],"explanation":"spends too much time online 花太多时间上网。"},{"q":"4","answer":"C","options":["refuse","forget","recommend","promise"],"explanation":"I recommend that you talk 我建议你和他谈谈。"},{"q":"5","answer":"D","options":["schedule","title","plate","behaviour"],"explanation":"talk about his behaviour 谈他的行为。"},{"q":"6","answer":"B","options":["afraid","attracted","ready","good"],"explanation":"be attracted to 被……吸引。"},{"q":"7","answer":"A","options":["unhealthy","useful","helpful","healthy"],"explanation":"too much time online is unhealthy 上网太久不健康。"},{"q":"8","answer":"C","options":["depend","agree","focus","win"],"explanation":"focus on other things 专注于别的事。"},{"q":"9","answer":"D","options":["force","stop","leave","encourage"],"explanation":"encourage him to try new hobbies 鼓励他尝试新爱好。"},{"q":"10","answer":"B","options":["agree","listen","follow","believe"],"explanation":"listen to sb 听某人的(只有 listen 能接 to you 表“听从”);agree/follow/believe 不接 to you。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'Becoming More Responsible', 'As we grow up, we have to be (1)____ for more and more things. At home, we should help our (2)____ and take care of ourselves. At school, we are responsible for our own studies and (3)____. Some teenagers think that being responsible means (4)____ their freedom, but this is not (5)____. In fact, responsibility and freedom go (6)____. When you show that you can be responsible, adults (7)____ you more. For example, if you always finish your homework on (8)____, your parents will not worry. Of course, no one becomes responsible in a single (9)____. We all make mistakes, but what matters is that we (10)____ from them.', 109, 3, '[{"q":"1","answer":"A","options":["responsible","ready","famous","free"],"explanation":"be responsible for 对……负责。"},{"q":"2","answer":"C","options":["clubs","plants","parents","teams"],"explanation":"at home,help our parents 在家帮父母。"},{"q":"3","answer":"D","options":["ballet","debate","schedule","behaviour"],"explanation":"studies and behaviour 学业和行为。"},{"q":"4","answer":"B","options":["finding","losing","keeping","getting"],"explanation":"means losing their freedom 意味着失去自由。"},{"q":"5","answer":"A","options":["true","late","busy","easy"],"explanation":"but this is not true 但这不是真的。"},{"q":"6","answer":"C","options":["away","down","together","up"],"explanation":"go together 相伴而行。"},{"q":"7","answer":"D","options":["leave","blame","force","trust"],"explanation":"adults trust you more 大人更信任你。"},{"q":"8","answer":"B","options":["hand","time","foot","head"],"explanation":"finish homework on time 按时完成作业。"},{"q":"9","answer":"A","options":["day","week","year","hour"],"explanation":"in a single day 在一天之内。"},{"q":"10","answer":"C","options":["hide","run","learn","fall"],"explanation":"learn from them 从错误中学习。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required1', 'U1', 'Choosing the Right Courses', 'At senior high school, choosing the right courses can be a real (1)____. In my first week, the school (2)____ helped me choose suitable ones: maths, English, and chemistry. I know that some subjects are (3)____, but I will work hard. My adviser also (4)____ that I sign up for advanced (5)____, because I like English and I am (6)____ at it. I had to choose extra-curricular (7)____, too. I tried to join the football team, but the coach said I did not play well (8)____. I was unhappy, but I will not (9)____. I will find a way to (10)____ on my own.', 104, 3, '[{"q":"1","answer":"D","options":["holiday","present","mistake","challenge"],"explanation":"a real challenge 真正的挑战。"},{"q":"2","answer":"B","options":["doctor","adviser","driver","writer"],"explanation":"the school adviser 学校顾问。"},{"q":"3","answer":"A","options":["difficult","easy","free","short"],"explanation":"but I will work hard 表转折,说明科目 difficult。"},{"q":"4","answer":"C","options":["refused","forgot","recommended","stopped"],"explanation":"adviser recommended that I sign up 建议我报名。"},{"q":"5","answer":"D","options":["ballet","football","weather","literature"],"explanation":"advanced literature,because I like English 高级文学。"},{"q":"6","answer":"B","options":["afraid","good","ready","sorry"],"explanation":"be good at 擅长。"},{"q":"7","answer":"A","options":["activities","mistakes","problems","lessons"],"explanation":"extra-curricular activities 课外活动。"},{"q":"8","answer":"C","options":["again","ago","enough","instead"],"explanation":"play well enough 踢得够好。"},{"q":"9","answer":"D","options":["win","smile","agree","quit"],"explanation":"I will not quit 我不会放弃。"},{"q":"10","answer":"B","options":["forget","improve","lose","fail"],"explanation":"find a way to improve 找办法提高。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·对话 Choosing a Club', '必修一 U1 · dialogue', 3, 'Adam: Hi Sam, have you chosen a club yet?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·短文 My First Day', '必修一 U1 · passage', 2, 'Today was my first day at senior high school.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·对话 Learning Strategies', '必修一 U1 · dialogue', 3, 'Amy: Li Ming, how do you study English so well?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·短文 Advice About Games', '必修一 U1 · passage', 2, 'My friend Chen Lei plays computer games too often.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·对话 Planning a Camp', '必修一 U1 · dialogue', 3, 'Max: Cao Jing, would you like to join a summer camp?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, '必修一 U1 听力·短文 Being Responsible', '必修一 U1 · passage', 2, 'As teenagers grow up, they become responsible for more things.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Letter of Advice（给同学写一封建议信）', 'A Letter of Advice', '你的同学李华最近沉迷电脑游戏、无法专心学习,向你求助。请用英语给他写一封建议信(约80词),内容包括:① 点明你了解他的问题与感受;② 给出至少两条建议及理由;③ 以鼓励的话收尾。', 'Your classmate Li Hua spends too much time playing computer games and cannot focus on his studies. Write him a letter of advice (about 80 words). Your letter should: 1) show that you understand his problem and how he feels; 2) give at least two pieces of advice, each with a reason; 3) end with a few words of encouragement.', '["用称呼开头,点明对方的问题(You wrote that …)","表示理解对方的感受(I understand that you feel …)","给出至少两条建议及理由(I think you should … / Why not … because …)","用鼓励的话和落款收尾(I am sure that … / Best wishes,)"]'::jsonb, 70, 100, 'Dear Li Hua, You wrote that you spend too much time playing computer games and cannot focus on your studies. I understand that you feel worried. I think you should make a daily schedule and set a fixed time for games. Why not try some new hobbies, such as sports or reading? They can help you relax in a healthier way. I am sure that if you keep trying, you will manage your time much better. Best wishes, Wang Ming', '【15 分制】A 档(13-15):结构完整(称呼/问题/理解/建议+理由/鼓励/落款)、建议≥2 条且有理由、语言准确多样;B 档(10-12):要点较全、少量语言错误;C 档(7-9):建议偏少或缺理由、句型简单、错误较多;D 档(0-6):内容不完整、结构混乱、错误多。', '["You wrote that you spend too much time playing computer games.（你来信说你花太多时间打游戏。）","I understand that you feel worried.（我理解你感到担心。）","I think you should make a daily schedule.（我认为你应该制定每日计划。）","Why not try some new hobbies, such as sports or reading?（何不尝试运动、阅读等新爱好?）","I am sure that if you keep trying, you will manage your time better.（我相信只要坚持,你会把时间管理得更好。）"]'::jsonb, '[{"wrong":"I think you should to make a plan.","correct":"I think you should make a plan.","note":"should 是情态动词,后接动词原形,不加 to。"},{"wrong":"Why not to try a new hobby?","correct":"Why not try a new hobby?","note":"Why not 后直接接动词原形。"},{"wrong":"I am sure you will manage your time good.","correct":"I am sure you will manage your time well.","note":"修饰动词 manage 用副词 well,不用形容词 good。"}]'::jsonb, '【建议信结构模板】
